/** $stroke_width stammt aus der Lucide-Zeit und wird ignoriert (Phosphor-Icons sind gefüllte Flächen). */
function elfzwo_icon( $name, $class = 'h-4 w-4', $stroke_width = 2 ) {
	$paths = elfzwo_icon_paths();
	// Das frühere Glitzer-Icon wirkte nach KI-Oberfläche — wo es noch gespeichert ist, wird ein Stern gezeigt.
	if ( 'sparkles' === $name ) {
		$name = 'star';
	}

	if ( ! isset( $paths[ $name ] ) ) {
		return '';
	}

	return sprintf(
		'<svg class="icon %s" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true">%s</svg>',
		esc_attr( $class ),
		$paths[ $name ]
	);
}

/**
 * Icon-Keys für Editor-Auswahlfelder (Block-Icon-Picker).
 */
function elfzwo_icon_keys() {
	return array_keys( elfzwo_icon_paths() );
}
